// Aaromach Arcade service worker (generated by the build; edits here are overwritten).
const CACHE = 'arcade-67f08246ff80';
const PRECACHE = [
 "./",
 "config.js",
 "games/coverage.html",
 "games/dispatch-board.html",
 "games/find-the-tool.html",
 "games/lift-panic.html",
 "games/pull-day.html",
 "games/rack-and-stack.html",
 "games/rough-in.html",
 "games/splice.html",
 "games/terminate.html",
 "games/tone-trace.html",
 "games/tool-drawer.html",
 "games/tools-lib.js",
 "icons/apple-touch-icon.png",
 "icons/favicon-32.png",
 "icons/icon-192.png",
 "icons/icon-512.png",
 "icons/icon.svg",
 "icons/maskable-512.png",
 "manifest.webmanifest",
 "scores.js"
];
const FONT_HOSTS = ['fonts.googleapis.com', 'fonts.gstatic.com'];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith('arcade-') && k !== CACHE).map(k => caches.delete(k))))
    .then(() => self.clients.claim()));
});
self.addEventListener('fetch', e => {
  const req = e.request; if (req.method !== 'GET') return;
  const url = new URL(req.url);
  const same = url.origin === location.origin, font = FONT_HOSTS.includes(url.hostname);
  if (!same && !font) return;                                   // Firebase, Firestore, auth: straight to the network
  if (same && url.pathname.startsWith('/__/')) return;         // Firebase Hosting reserved URLs (auth helpers, init.json)
  if (req.mode === 'navigate') {
    // Pages: network first so a new deploy shows up, cached copy when offline.
    e.respondWith(fetch(req).then(res => { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); return res; })
      .catch(() => caches.match(req, { ignoreSearch: true }).then(r => r || caches.match('./'))));
    return;
  }
  // Everything else: cache first, refreshed in the background.
  e.respondWith(caches.match(req, { ignoreSearch: same }).then(hit => {
    const net = fetch(req).then(res => { if (res.ok || res.type === 'opaque') { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); } return res; }).catch(() => hit);
    return hit || net;
  }));
});
